/* ==========================================================
   Automatic Overcharge action selection
   ========================================================== */

.frame-helm-action-overcharge-warning {
  display: flex !important;
  align-items: center;
  gap: 0.35rem;
  margin-top: 0.35rem;
  color: var(--fh-amber);
  font-family: monospace;
  font-size: 0.7rem;
  font-style: normal;
  font-weight: 700;
  letter-spacing: 0.04em;
  text-transform: uppercase;
  text-shadow: 0 0 6px rgba(255, 184, 74, 0.34);
}

.frame-helm-action-overcharge-warning i {
  flex: 0 0 auto;
}

.frame-helm-quick-choice-overcharge {
  border-color: var(--fh-amber-muted) !important;
  background:
    linear-gradient(
      90deg,
      rgba(255, 184, 74, 0.12),
      transparent
    ),
    rgba(18, 16, 9, 0.94) !important;
  box-shadow:
    inset 3px 0 0 var(--fh-amber),
    0 0 10px rgba(255, 184, 74, 0.08) !important;
}

.frame-helm-quick-choice-overcharge:hover {
  border-color: var(--fh-amber) !important;
  box-shadow:
    inset 4px 0 0 var(--fh-amber),
    0 0 14px rgba(255, 184, 74, 0.18) !important;
}

.frame-helm-overcharge-warning-panel {
  display: flex;
  flex: 0 0 auto;
  align-items: flex-start;
  gap: 0.6rem;
  width: 100%;
  height: auto;
  min-height: 3rem;
  border: 1px solid var(--fh-amber);
  border-left: 4px solid var(--fh-amber);
  background:
    linear-gradient(
      90deg,
      rgba(255, 184, 74, 0.17),
      transparent
    ),
    rgba(23, 16, 5, 0.86);
  padding: 0.65rem 0.75rem;
  color: #ffe2ad;
  font-size: 0.75rem;
  line-height: 1.35;
  box-shadow:
    inset 0 0 12px rgba(255, 184, 74, 0.05),
    0 0 10px rgba(255, 184, 74, 0.09);
}

.frame-helm-overcharge-warning-panel i {
  flex: 0 0 1.2rem;
  width: 1.2rem;
  margin-top: 0.08rem;
  color: var(--fh-amber);
  font-size: 1rem;
  text-align: center;
  text-shadow: 0 0 7px rgba(255, 184, 74, 0.45);
}

.frame-helm-overcharge-warning-panel span {
  min-width: 0;
  white-space: normal;
  overflow-wrap: anywhere;
}

.frame-helm-auto-overcharge-execute:not(:disabled) {
  border-color: var(--fh-amber) !important;
  background:
    linear-gradient(
      90deg,
      rgba(255, 184, 74, 0.22),
      transparent
    ),
    rgba(24, 17, 6, 0.96) !important;
  color: #fff0cf !important;
  box-shadow:
    inset 5px 0 0 var(--fh-amber),
    0 0 14px rgba(255, 184, 74, 0.16) !important;
}

.frame-helm-auto-overcharge-execute:not(:disabled):hover {
  background:
    linear-gradient(
      90deg,
      rgba(255, 184, 74, 0.32),
      transparent
    ),
    rgba(31, 21, 7, 0.98) !important;
  box-shadow:
    inset 6px 0 0 var(--fh-amber),
    0 0 18px rgba(255, 184, 74, 0.25) !important;
}
